#include "ModStore.h"
#include "PlatformServices.h"
#include "SceneFingerprint.h"
#include <filesystem>
#include <algorithm>
namespace JudasMods {
namespace {
using AuthoringJSON::require;using AuthoringJSON::keys;
std::string Filename(const std::string& id,const std::string& version,const std::string& hash){return id+"--"+version+"--"+hash+".judasmod";}
JSON Index(const std::vector<Installed>& values){JSON j=JSON::array();for(auto& v:values)j.push_back({{"id",v.id},{"version",v.version},{"sha256",v.hash},{"file",v.file}});return {{"format",1},{"installed",j}};}
JSON Index(const std::vector<Loadout>& values){JSON j=JSON::array();for(auto& v:values)j.push_back({{"id",v.id},{"version",v.version},{"sha256",v.hash},{"trustedHash",v.trustedHash}});return {{"format",1},{"selected",j}};}
void Identity(const std::string& id,const std::string& version,const std::string& hash){std::array<unsigned,3> parts{};require(ValidIdentity(id)&&ParseVersion(version,parts)&&hash.size()==64&&hash.find_first_not_of("0123456789abcdef")==std::string::npos,"invalid installed mod identity");}
bool Optional(ContentStorage& store,const char* name,std::string& bytes,std::string& error){std::vector<std::string> names;if(!store.List(names,256,error))return false;if(std::find(names.begin(),names.end(),name)==names.end()){bytes.clear();return true;}return store.Read(name,bytes,Limits::Metadata,error);}
}
Store::Store(std::string root):m_installed((std::filesystem::u8path(root)/"Installed").u8string()),m_selection((std::filesystem::u8path(root)/"Loadout").u8string()),m_cache((std::filesystem::u8path(root)/"Cache").u8string()),m_transaction(root){}
bool GameModDirectory(const Contract& c,std::string& root,std::string& error){if(!c.enabled||!ValidIdentity(c.game)){error="game modding is disabled/invalid";return false;}auto user=PlatformUserDataDirectory(error);if(user.empty())return false;root=(std::filesystem::u8path(user)/"judas"/"mods"/c.game).u8string();return true;}
bool Store::ReadIndex(std::vector<Installed>& out,std::string& error){try{std::string bytes;require(Optional(m_installed,"index.json",bytes,error),error);if(bytes.empty()){out.clear();return true;}auto j=AuthoringJSON::parse(bytes);keys(j,{"format","installed"},"installed index");require(j.at("format")==1&&j.at("installed").is_array()&&j.at("installed").size()<=128,"installed index version/count");std::vector<Installed> list;std::set<std::string> files;for(auto& v:j.at("installed")){keys(v,{"id","version","sha256","file"},"installed version");Installed i{v.at("id"),v.at("version"),v.at("sha256"),v.at("file")};Identity(i.id,i.version,i.hash);require(i.file==Filename(i.id,i.version,i.hash)&&files.insert(i.file).second,"invalid/duplicate installed version file");list.push_back(i);}out=std::move(list);return true;}catch(const std::exception& e){error=e.what();return false;}}
bool Store::ReadLoadout(std::vector<Loadout>& out,std::string& error){try{std::string bytes;require(Optional(m_selection,"selected.json",bytes,error),error);if(bytes.empty()){out.clear();return true;}auto j=AuthoringJSON::parse(bytes);keys(j,{"format","selected"},"loadout");require(j.at("format")==1&&j.at("selected").is_array()&&j.at("selected").size()<=Limits::Mods,"loadout version/count");std::vector<Loadout> list;std::set<std::string> ids;for(auto& v:j.at("selected")){keys(v,{"id","version","sha256","trustedHash"},"selected version");Loadout i{v.at("id"),v.at("version"),v.at("sha256"),v.at("trustedHash")};Identity(i.id,i.version,i.hash);require((i.trustedHash.empty()||i.trustedHash==i.hash)&&ids.insert(i.id).second,"invalid trust/duplicate selected ID");list.push_back(i);}out=std::move(list);return true;}catch(const std::exception& e){error=e.what();return false;}}
bool Store::WriteIndex(const std::vector<Installed>& v,std::string& e){return m_installed.Publish("index.json",Index(v).dump(2),e);}
bool Store::WriteLoadout(const std::vector<Loadout>& v,std::string& e){return m_selection.Publish("selected.json",Index(v).dump(2),e);}
bool Store::List(std::vector<Installed>& installed,std::vector<Loadout>& selected,std::string& e){return ReadIndex(installed,e)&&ReadLoadout(selected,e);}
bool Store::Selected(const std::vector<Installed>& installed,const std::vector<Loadout>& selected,std::vector<Selection>& out,std::string& e){try{std::vector<Selection> list;size_t total=0;for(auto& s:selected){auto it=std::find_if(installed.begin(),installed.end(),[&](auto& i){return i.id==s.id&&i.version==s.version&&i.hash==s.hash;});require(it!=installed.end(),"required mod not installed: "+s.id+" "+s.version+" "+s.hash);std::string bytes;require(m_installed.Read(it->file,bytes,Limits::Package,e),"installed "+s.id+": "+e);require(total<=Limits::Storage-bytes.size(),"selected package aggregate exceeds 512 MiB");total+=bytes.size();auto p=std::make_shared<Package>();require(DecodePackage(bytes,*p,e),it->file+": "+e);require(p->hash==it->hash&&p->manifest.id==it->id&&p->manifest.version==it->version,"installed index/payload disagreement");list.push_back({p,s.trustedHash});}out=std::move(list);return true;}catch(const std::exception& ex){e=ex.what();return false;}}
bool Store::Install(const Contract& c,const Package& p,std::string& e,const std::function<bool()>& cancel){try{
 auto transaction=m_transaction.Exclusive(".store-lock",e);require(bool(transaction),e);require(c.enabled,"game modding is disabled");std::string bytes;require(EncodePackage(p,bytes,e),e);require(p.hash==SceneFingerprintSha256(bytes),"package hash must identify the complete validated payload");const auto& m=p.manifest;require(m.game==c.game&&VersionMatches(c.gameVersion,m.gameVersion)&&VersionMatches(c.version,m.contractVersion),"package game/contract incompatible");require(!m.executable||c.executable,"game forbids executable mods");for(auto& a:m.assets)require(c.additions.count(a.type),"game denies addition type: "+a.type);for(auto& r:m.replacements){auto t=c.replacements.find(r.target);require(t!=c.replacements.end()&&t->second.revision==r.revision&&t->second.target.kind==r.provider.kind,"protected/incompatible replacement request: "+r.target);}
 std::vector<Installed> index;require(ReadIndex(index,e),e);auto file=Filename(m.id,m.version,p.hash);if(std::find_if(index.begin(),index.end(),[&](auto& i){return i.file==file;})!=index.end())return true;require(index.size()<128,"installed version count exceeds 128");std::vector<std::string> actual;require(m_installed.List(actual,256,e),e);size_t total=0;for(auto& name:actual)if(name.size()>=9&&name.substr(name.size()-9)==".judasmod"){std::string old;require(m_installed.Read(name,old,Limits::Package,e),e);require(total<=Limits::Storage-old.size(),"installed package budget exceeded");total+=old.size();}require(bytes.size()<=Limits::Storage-total,"installation exceeds 512 MiB; remove an unused version");require(!cancel||!cancel(),"mod install cancelled");m_installed.boundary=boundary;if(std::find(actual.begin(),actual.end(),file)==actual.end())require(m_installed.Publish(file,bytes,e,true),e);else{std::string retained;require(m_installed.Read(file,retained,Limits::Package,e)&&retained==bytes,"interrupted install retained a different/corrupt immutable file");}if(boundary)boundary("package-published");require(!cancel||!cancel(),"mod install cancelled; previous index retained");index.push_back({m.id,m.version,p.hash,file});require(WriteIndex(index,e),e);e.clear();return true;
 }catch(const std::exception& ex){e=ex.what();return false;}}
bool Store::Enable(const Contract& c,const std::string& id,const std::string& version,const std::string& hash,bool trust,std::string& e){try{auto transaction=m_transaction.Exclusive(".store-lock",e);require(bool(transaction),e);std::vector<Installed> installed;std::vector<Loadout> selected;require(List(installed,selected,e),e);Identity(id,version,hash);auto it=std::find_if(installed.begin(),installed.end(),[&](auto& v){return v.id==id&&v.version==version&&v.hash==hash;});require(it!=installed.end(),"selected version is not installed");selected.erase(std::remove_if(selected.begin(),selected.end(),[&](auto& v){return v.id==id;}),selected.end());selected.push_back({id,version,hash,trust?hash:std::string()});std::vector<Selection> packages;require(Selected(installed,selected,packages,e),e);Resolution r;require(Resolve(c,packages,r,e),e);require(WriteLoadout(selected,e),e);e.clear();return true;}catch(const std::exception& ex){e=ex.what();return false;}}
bool Store::Disable(const std::string& id,std::string& e){auto transaction=m_transaction.Exclusive(".store-lock",e);if(!transaction)return false;std::vector<Loadout> selected;if(!ReadLoadout(selected,e))return false;selected.erase(std::remove_if(selected.begin(),selected.end(),[&](auto& v){return v.id==id;}),selected.end());return WriteLoadout(selected,e);}
bool Store::Remove(const std::string& id,const std::string& version,const std::string& hash,std::string& e){try{auto transaction=m_transaction.Exclusive(".store-lock",e);require(bool(transaction),e);std::vector<Installed> index;std::vector<Loadout> selected;require(List(index,selected,e),e);Identity(id,version,hash);require(std::none_of(selected.begin(),selected.end(),[&](auto& v){return v.id==id&&v.version==version&&v.hash==hash;}),"disable this version first; dependents will require correction");auto file=Filename(id,version,hash);auto it=std::find_if(index.begin(),index.end(),[&](auto& v){return v.file==file;});require(it!=index.end(),"version is not installed");std::string retained;require(m_installed.Read(file,retained,Limits::Package,e),e);require(m_installed.Remove(file,e),e);index.erase(it);if(!WriteIndex(index,e)){auto publication=e;std::string recovery;require(m_installed.Publish(file,retained,recovery,true),"index publication failed and payload restoration failed: "+publication+"; "+recovery);throw std::runtime_error("index publication failed; original version restored: "+publication);}std::string cleanup;CollectCache(index,cleanup);e.clear();return true;}catch(const std::exception& ex){e=ex.what();return false;}}
// Reclaim only immutable cache entries no installed version still owns. Active
// previews/read jobs hold file leases: collection skips those rather than breaking
// an existing session. Shared unchanged content remains until its last owner goes.
bool Store::CollectCache(const std::vector<Installed>& installed,std::string& e){try{
 std::set<std::string> retained;for(const auto& item:installed){std::string bytes;require(m_installed.Read(item.file,bytes,Limits::Package,e),e);Package package;require(DecodePackage(bytes,package,e),e);for(const auto& file:package.manifest.files)retained.insert(SceneFingerprintSha256("Judas.ModFile.1:"+package.manifest.id+":"+file.path+":"+file.hash)+std::filesystem::u8path(file.path).extension().u8string());}
 std::vector<std::string> names;require(m_cache.List(names,Limits::Mods*Limits::Files+256,e),e);for(const auto& name:names)if(name!=".publish-lock"&&name.rfind(".tmp-",0)!=0&&!retained.count(name)){std::string busy;m_cache.Remove(name,busy);}e.clear();return true;
 }catch(const std::exception& ex){e=ex.what();return false;}}
bool Store::Materialize(Snapshot& s,bool installedLeases,std::string& e){try{
 std::vector<std::string> cached;require(m_cache.List(cached,Limits::Mods*Limits::Files+256,e),e);std::set<std::string> existing(cached.begin(),cached.end());size_t cachedBytes=0;for(auto& f:cached){if(f==".publish-lock"||f.rfind(".tmp-",0)==0)continue;std::string bytes;require(m_cache.Read(f,bytes,Limits::File,e),e);require(cachedBytes<=Limits::Storage-bytes.size(),"cache storage exceeds 512 MiB");cachedBytes+=bytes.size();}
 for(auto& p:s.resolution.ordered){auto filename=Filename(p.package->manifest.id,p.package->manifest.version,p.package->hash);if(installedLeases){auto lease=m_installed.Lease(filename,e);require(bool(lease),e);s.leases.push_back(lease);}for(auto& f:p.package->manifest.files){auto extension=std::filesystem::u8path(f.path).extension().u8string();auto name=SceneFingerprintSha256("Judas.ModFile.1:"+p.package->manifest.id+":"+f.path+":"+f.hash)+extension;require(!extension.empty()&&extension.size()<32&&extension.find_first_not_of(".abcdefghijklmnopqrstuvwxyz0123456789") == std::string::npos,"unsupported payload extension");if(existing.count(name)){std::string bytes;require(m_cache.Read(name,bytes,Limits::File,e)&&SceneFingerprintSha256(bytes)==f.hash,"immutable cache integrity failure: "+p.package->manifest.id+"/"+f.path);}else{require(cachedBytes<=Limits::Storage-f.size,"cache capacity exhausted; remove unused installed/cache versions");require(m_cache.Publish(name,p.package->files.at(f.path),e,true),e);cachedBytes+=size_t(f.size);existing.insert(name);}auto cacheLease=m_cache.Lease(name,e);require(bool(cacheLease),e);s.leases.push_back(cacheLease);s.files[p.package->manifest.id+":"+f.path]=m_cache.Path(name);}}
 e.clear();return true;
 }catch(const std::exception& ex){e=ex.what();return false;}}
bool Store::Preview(const Contract& c,const std::vector<Selection>& selected,Snapshot& out,std::string& e){Snapshot s;if(!Resolve(c,selected,s.resolution,e)||!Materialize(s,false,e))return false;out=std::move(s);return true;}
bool Store::Freeze(const Contract& c,Snapshot& out,std::string& e){try{
 auto transaction=m_transaction.Exclusive(".store-lock",e);require(bool(transaction),e);
 std::vector<Installed> index;std::vector<Loadout> selected;require(List(index,selected,e),e);
 std::string cleanup;if(!selected.empty())require(CollectCache(index,cleanup),cleanup);std::vector<Selection> packages;require(Selected(index,selected,packages,e),e);Snapshot s;
 require(Resolve(c,packages,s.resolution,e),e);if(!packages.empty())require(Materialize(s,true,e),e);
 out=std::move(s);e.clear();return true;
 }catch(const std::exception& ex){e=ex.what();return false;}}
}
